import sys
import os
import csv
import io
import json


def main():
    args = sys.argv[1:]

    # Parse arguments
    indent = None
    path = None

    i = 0
    while i < len(args):
        if args[i] == '--indent':
            if i + 1 >= len(args):
                print("csv2json.py: usage: python csv2json.py PATH [--indent N]", file=sys.stderr)
                sys.exit(2)
            indent_str = args[i + 1]
            try:
                indent = int(indent_str)
                if indent < 0:
                    raise ValueError()
            except ValueError:
                print("csv2json.py: usage: python csv2json.py PATH [--indent N]", file=sys.stderr)
                sys.exit(2)
            i += 2
        else:
            if path is not None:
                print("csv2json.py: usage: python csv2json.py PATH [--indent N]", file=sys.stderr)
                sys.exit(2)
            path = args[i]
            i += 1

    if path is None:
        print("csv2json.py: usage: python csv2json.py PATH [--indent N]", file=sys.stderr)
        sys.exit(2)

    # Check if file exists and is a regular file
    if not os.path.exists(path) or not os.path.isfile(path):
        print(f"csv2json.py: no such file: {path}", file=sys.stderr)
        sys.exit(2)

    # Read the file with UTF-8 encoding, handling BOM
    # We need to handle blank lines correctly. The spec says "completely empty (a blank line)" are skipped.
    # We will iterate through the file line by line, accumulating lines into a buffer until a complete
    # CSV record is formed. A complete record is identified by the fact that we are not inside a
    # quoted field (i.e., the number of unescaped quotes is even, or more precisely, we are outside quotes).

    records = []
    header = None
    record_num = 0

    buffer = ""

    try:
        with open(path, 'r', encoding='utf-8-sig', newline='') as f:
            for raw_line in f:
                # raw_line includes the line ending (e.g., \n or \r\n)
                buffer += raw_line

                # Determine if the buffer contains a complete CSV record.
                # We iterate through the buffer to find if we are currently inside a quoted field.
                # A field is quoted if it starts with a double quote. Inside a quoted field, quotes are doubled "".

                in_quoted_field = False
                idx = 0
                n_buf = len(buffer)

                while idx < n_buf:
                    char = buffer[idx]
                    if char == '"':
                        if in_quoted_field:
                            # Check if this is an escaped quote ""
                            if idx + 1 < n_buf and buffer[idx + 1] == '"':
                                idx += 2
                                continue
                            else:
                                # End of quoted field
                                in_quoted_field = False
                        else:
                            # Start of quoted field
                            in_quoted_field = True
                    idx += 1

                # If we are not inside a quoted field, the record is complete.
                if not in_quoted_field:
                    # Check if the record is blank.
                    # A blank record is one that consists solely of line endings (or is empty).
                    # We strip the line ending from the end of the buffer.
                    rec_content = buffer
                    if rec_content.endswith('\r\n'):
                        rec_content = rec_content[:-2]
                    elif rec_content.endswith('\n'):
                        rec_content = rec_content[:-1]
                    elif rec_content.endswith('\r'):
                        rec_content = rec_content[:-1]

                    # If the content is empty, it's a blank line. Skip it.
                    if rec_content == '':
                        buffer = ""
                        continue

                    # Parse the record using csv.reader
                    # We use io.StringIO to treat the buffer as a stream
                    try:
                        reader = csv.reader(io.StringIO(buffer), delimiter=',', quotechar='"',
                                            doublequote=True, skipinitialspace=False)
                        row = next(reader)
                    except csv.Error as e:
                        print(f"csv2json.py: invalid CSV: {e}", file=sys.stderr)
                        sys.exit(2)
                    except StopIteration:
                        row = []

                    record_num += 1

                    if record_num == 1:
                        # Header
                        header = row
                    else:
                        # Data record
                        if len(row) < len(header):
                            # Pad with None
                            padded_row = row + [None] * (len(header) - len(row))
                            obj = {}
                            for idx_h, key in enumerate(header):
                                obj[key] = padded_row[idx_h]
                            records.append(obj)
                        elif len(row) > len(header):
                            print(f"csv2json.py: record {record_num} has {len(row)} fields, expected {len(header)}", file=sys.stderr)
                            sys.exit(1)
                        else:
                            obj = {}
                            for idx_h, key in enumerate(header):
                                obj[key] = row[idx_h]
                            records.append(obj)

                    buffer = ""

    except Exception as e:
        # If there's an error reading the file that wasn't caught earlier
        print(f"csv2json.py: no such file: {path}", file=sys.stderr)
        sys.exit(2)

    # If there's remaining buffer, it's an incomplete record. 
    # We can ignore it as the file might not end with a newline, but if it's not empty, 
    # it might be a data record. However, without a line ending, csv.reader might behave differently.
    # Given the spec implies well-formed CSV with records separated by newlines, we assume 
    # if buffer is not empty and not skipped, it should have been processed if it ended with a newline.
    # If it doesn't end with a newline, it's an incomplete record at EOF. We ignore it for robustness,
    # or we could try to parse it. Let's try to parse it if it's not empty.
    if buffer:
        # Check if it's blank
        rec_content = buffer
        if rec_content.endswith('\r\n'):
            rec_content = rec_content[:-2]
        elif rec_content.endswith('\n'):
            rec_content = rec_content[:-1]
        elif rec_content.endswith('\r'):
            rec_content = rec_content[:-1]

        if rec_content != '':
            try:
                reader = csv.reader(io.StringIO(buffer), delimiter=',', quotechar='"',
                                    doublequote=True, skipinitialspace=False)
                row = next(reader)
            except csv.Error:
                pass # Ignore incomplete/malformed trailing record
            except StopIteration:
                row = []

            if row:
                record_num += 1
                if record_num == 1:
                    header = row
                else:
                    if len(row) < len(header):
                        padded_row = row + [None] * (len(header) - len(row))
                        obj = {}
                        for idx_h, key in enumerate(header):
                            obj[key] = padded_row[idx_h]
                        records.append(obj)
                    elif len(row) > len(header):
                        print(f"csv2json.py: record {record_num} has {len(row)} fields, expected {len(header)}", file=sys.stderr)
                        sys.exit(1)
                    else:
                        obj = {}
                        for idx_h, key in enumerate(header):
                            obj[key] = row[idx_h]
                        records.append(obj)

    if header is None:
        print(f"csv2json.py: empty file: {path}", file=sys.stderr)
        sys.exit(2)

    # Generate JSON output
    if indent is not None:
        output = json.dumps(records, indent=indent, ensure_ascii=False) + '\n'
    else:
        output = json.dumps(records, ensure_ascii=False) + '\n'

    sys.stdout.write(output)
    sys.exit(0)


if __name__ == '__main__':
    main()
