"""Parser for the tmpl template engine.

Converts a list of tokens into a tree of nodes representing the template structure.
"""

from .lexer import (
    Token, 
    TemplateSyntaxError, 
    tokenize,
    TemplateError
)
import typing
import re

# Node Types
class TextNode(typing.NamedTuple):
    value: str

class OutputNode(typing.NamedTuple):
    value: str  # The raw expression string

class IfNode(typing.NamedTuple):
    conditions: list[tuple[str, list, int]] # (cond_str, nodes, lineno)
    else_nodes: list
    endif_lineno: int
    start_lineno: int

class ForNode(typing.NamedTuple):
    var_name: str
    expr: str
    body_nodes: list
    else_nodes: list
    endfor_lineno: int
    start_lineno: int

# Reserved words for expression atoms
RESERVED_WORDS = {'and', 'or', 'not', 'in'}

# Filter definitions
FILTERS_NO_ARGS = {'upper', 'lower', 'trim', 'length', 'first', 'last', 'reverse', 'items'}
FILTERS_WITH_ARGS = {
    'join': 'str',
    'default': 'literal',  # str or int
    'truncate': 'int'
}

def parse(source: str) -> list:
    """Parse the template source into a list of nodes.

    Args:
        source: The raw template text.

    Returns:
        A list of node objects.

    Raises:
        TemplateSyntaxError: If the template contains syntax errors.
    """
    tokens = tokenize(source)
    return _parse_tokens(tokens)

def _parse_tokens(tokens: list[Token]) -> list:
    nodes: list = []
    # Stack for block contexts
    # Each item: {'type': 'if' | 'for', 'nodes_idx': int, 'active_branch_nodes': list, 'else_nodes': list|None}
    block_stack: list[dict] = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token.kind == 'text':
            nodes.append(TextNode(token.value))
            i += 1
            continue

        if token.kind == 'var':
            expr = token.value.strip()
            if not expr:
                raise TemplateSyntaxError("Empty expression", token.lineno)
            parse_value_expression(expr, token.lineno)
            nodes.append(OutputNode(expr))
            i += 1
            continue

        if token.kind == 'block':
            content = token.value.strip()

            if content.startswith('for '):
                rest = content[4:].strip()
                if ' in ' not in rest:
                    raise TemplateSyntaxError("Malformed for loop", token.lineno)
                parts = rest.split(' in ', 1)
                var_name = parts[0].strip()
                expr = parts[1].strip()
                if not var_name or not var_name.isidentifier() or var_name in RESERVED_WORDS:
                    raise TemplateSyntaxError(f"Invalid variable name '{var_name}'", token.lineno)
                if not expr:
                    raise TemplateSyntaxError("Empty expression in for loop", token.lineno)
                parse_value_expression(expr, token.lineno)

                active_nodes = []
                # Placeholder node. The body_nodes list is mutable and will be filled.
                for_node = ForNode(var_name, expr, active_nodes, None, None, token.lineno)
                nodes.append(for_node)
                block_stack.append({
                    'type': 'for',
                    'nodes_idx': len(nodes) - 1,
                    'active_branch_nodes': active_nodes,
                    'else_nodes': None
                })
                i += 1
                continue

            elif content.startswith('if '):
                cond_str = content[3:].strip()
                if not cond_str:
                    raise TemplateSyntaxError("Empty condition in if", token.lineno)
                parse_condition(cond_str, token.lineno)

                active_nodes = []
                if_node = IfNode([(cond_str, active_nodes, token.lineno)], None, None, token.lineno)
                nodes.append(if_node)
                block_stack.append({
                    'type': 'if',
                    'nodes_idx': len(nodes) - 1,
                    'active_branch_nodes': active_nodes,
                    'else_nodes': None
                })
                i += 1
                continue

            elif content.startswith('elif '):
                cond_str = content[4:].strip()
                if not cond_str:
                    raise TemplateSyntaxError("Empty condition in elif", token.lineno)
                parse_condition(cond_str, token.lineno)

                if not block_stack or block_stack[-1]['type'] != 'if':
                    raise TemplateSyntaxError("Unexpected elif", token.lineno)

                ctx = block_stack[-1]
                if ctx['else_nodes'] is not None:
                    raise TemplateSyntaxError("Unexpected elif after else", token.lineno)

                active_nodes = []
                nodes_idx = ctx['nodes_idx']
                old_if_node: IfNode = nodes[nodes_idx]
                new_conditions = list(old_if_node.conditions) + [(cond_str, active_nodes, token.lineno)]
                new_if_node = IfNode(new_conditions, old_if_node.else_nodes, old_if_node.endif_lineno, old_if_node.start_lineno)
                nodes[nodes_idx] = new_if_node

                # Switch active context to the new elif branch
                ctx['active_branch_nodes'] = active_nodes
                i += 1
                continue

            elif content == 'else':
                if not block_stack or block_stack[-1]['type'] != 'if':
                    raise TemplateSyntaxError("Unexpected else", token.lineno)

                ctx = block_stack[-1]
                if ctx['else_nodes'] is not None:
                    raise TemplateSyntaxError("Multiple else blocks in if", token.lineno)

                ctx['else_nodes'] = []
                # Switch active context to the else branch
                ctx['active_branch_nodes'] = ctx['else_nodes']
                i += 1
                continue

            elif content == 'endif':
                if not block_stack or block_stack[-1]['type'] != 'if':
                    raise TemplateSyntaxError("Unexpected endif", token.lineno)

                ctx = block_stack.pop()
                nodes_idx = ctx['nodes_idx']
                old_if_node: IfNode = nodes[nodes_idx]
                new_if_node = IfNode(
                    old_if_node.conditions,
                    ctx['else_nodes'],
                    token.lineno,
                    old_if_node.start_lineno
                )
                nodes[nodes_idx] = new_if_node
                i += 1
                continue

            elif content == 'endfor':
                if not block_stack or block_stack[-1]['type'] != 'for':
                    raise TemplateSyntaxError("Unexpected endfor", token.lineno)

                ctx = block_stack.pop()
                nodes_idx = ctx['nodes_idx']
                old_for_node: ForNode = nodes[nodes_idx]
                new_for_node = ForNode(
                    old_for_node.var_name,
                    old_for_node.expr,
                    old_for_node.body_nodes,
                    ctx['else_nodes'],
                    token.lineno,
                    old_for_node.start_lineno
                )
                nodes[nodes_idx] = new_for_node
                i += 1
                continue

            else:
                word = content.split()[0] if content.split() else content
                raise TemplateSyntaxError(f"Unknown statement '{word}'", token.lineno)

        else:
            i += 1

    if block_stack:
        ctx = block_stack[-1]
        if ctx['type'] == 'if':
            old_if_node: IfNode = nodes[ctx['nodes_idx']]
            raise TemplateSyntaxError("Unclosed if block", old_if_node.start_lineno)
        else:
            old_for_node: ForNode = nodes[ctx['nodes_idx']]
            raise TemplateSyntaxError("Unclosed for block", old_for_node.start_lineno)

    return nodes

def parse_value_expression(expr: str, lineno: int):
    """Validate a value expression syntax."""
    tokens = _tokenize_expression(expr)
    if not tokens:
        raise TemplateSyntaxError("Empty expression", lineno)
    _parse_expression_tokens(tokens, 0, lineno)

def _tokenize_expression(expr: str) -> list:
    """Split expression into atoms and filters."""
    result = []
    parts = expr.split('|')
    atom_part = parts[0].strip()
    if not atom_part:
        return []
    result.append(('atom', atom_part))

    for part in parts[1:]:
        part = part.strip()
        if not part:
            raise TemplateSyntaxError("Empty filter", 0)

        if ':' in part:
            name, arg = part.split(':', 1)
            name = name.strip()
            arg = arg.strip()
        else:
            name = part.strip()
            arg = None

        if not name:
            raise TemplateSyntaxError("Empty filter name", 0)

        result.append(('filter', name, arg))

    return result

def _parse_expression_tokens(tokens: list, idx: int, lineno: int):
    # Parse atom
    if idx >= len(tokens) or tokens[idx][0] != 'atom':
        raise TemplateSyntaxError("Expected atom", lineno)
    atom = tokens[idx][1]
    if not _is_valid_atom(atom):
        raise TemplateSyntaxError(f"Invalid expression atom '{atom}'", lineno)
    idx += 1

    # Parse filters
    while idx < len(tokens):
        if tokens[idx][0] != 'filter':
            raise TemplateSyntaxError(f"Unexpected token in expression", lineno)
        name = tokens[idx][1]
        arg = tokens[idx][2]
        validate_filter(name, arg, lineno)
        idx += 1

def _is_valid_atom(atom: str) -> bool:
    """Check if atom is valid variable path or literal."""
    # Literal
    if len(atom) >= 2 and ((atom.startswith('"') and atom.endswith('"')) or (atom.startswith("'") and atom.endswith("'"))):
        return True

    # Variable
    # Name.segment...
    # Name is [A-Za-z_][A-Za-z0-9_]*
    # Segment is .name or .integer
    pattern = r'^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*|\.[0-9]+)*$'
    if re.match(pattern, atom):
        return True

    return False

def validate_filter(name: str, arg, lineno: int):
    if name in FILTERS_NO_ARGS:
        if arg is not None:
            raise TemplateSyntaxError(f"Filter '{name}' does not take arguments", lineno)
    elif name in FILTERS_WITH_ARGS:
        if arg is None:
            raise TemplateSyntaxError(f"Filter '{name}' requires an argument", lineno)
        expected_type = FILTERS_WITH_ARGS[name]
        if expected_type == 'int':
            try:
                val = int(arg)
                if name == 'truncate' and val < 0:
                    raise TemplateSyntaxError(f"Negative argument for truncate", lineno)
            except ValueError:
                raise TemplateSyntaxError(f"Invalid integer argument for filter '{name}'", lineno)
        elif expected_type == 'str':
            pass
        elif expected_type == 'literal':
            try:
                int(arg)
            except ValueError:
                if not isinstance(arg, str):
                     raise TemplateSyntaxError(f"Invalid argument for filter '{name}'", lineno)
    else:
        raise TemplateSyntaxError(f"Unknown filter '{name}'", lineno)

def parse_condition(cond: str, lineno: int):
    tokens = _tokenize_condition(cond)
    if not tokens:
        raise TemplateSyntaxError("Empty condition", lineno)
    end_idx = _parse_condition_tokens(tokens, 0, lineno)
    if end_idx != len(tokens):
        raise TemplateSyntaxError("Invalid condition syntax", lineno)

def _tokenize_condition(cond: str) -> list:
    words = cond.split()
    tokens = []
    for w in words:
        if w in ('and', 'or'):
            tokens.append(('logical', w))
        elif w in ('not',):
            tokens.append(('logical', w))
        elif w in ('==', '!=', '<', '<=', '>', '>='):
            tokens.append(('op', w))
        else:
            tokens.append(('atom', w))
    return tokens

def _parse_condition_tokens(tokens: list, idx: int, lineno: int) -> int:
    return _parse_or_expr(tokens, idx, lineno)

def _parse_or_expr(tokens: list, idx: int, lineno: int) -> int:
    idx = _parse_and_expr(tokens, idx, lineno)
    while idx < len(tokens) and tokens[idx][0] == 'logical' and tokens[idx][1] == 'or':
        idx += 1
        idx = _parse_and_expr(tokens, idx, lineno)
    return idx

def _parse_and_expr(tokens: list, idx: int, lineno: int) -> int:
    idx = _parse_not_expr(tokens, idx, lineno)
    while idx < len(tokens) and tokens[idx][0] == 'logical' and tokens[idx][1] == 'and':
        idx += 1
        idx = _parse_not_expr(tokens, idx, lineno)
    return idx

def _parse_not_expr(tokens: list, idx: int, lineno: int) -> int:
    if idx < len(tokens) and tokens[idx][0] == 'logical' and tokens[idx][1] == 'not':
        idx += 1
        idx = _parse_not_expr(tokens, idx, lineno)
    else:
        idx = _parse_comparison_expr(tokens, idx, lineno)
    return idx

def _parse_comparison_expr(tokens: list, idx: int, lineno: int) -> int:
    idx = _parse_atom_expr(tokens, idx, lineno)
    if idx < len(tokens) and tokens[idx][0] == 'op':
        idx += 1
        idx = _parse_atom_expr(tokens, idx, lineno)
    return idx

def _parse_atom_expr(tokens: list, idx: int, lineno: int) -> int:
    if idx >= len(tokens) or tokens[idx][0] != 'atom':
        raise TemplateSyntaxError("Expected expression", lineno)
    atom = tokens[idx][1]
    if not _is_valid_atom(atom):
        raise TemplateSyntaxError(f"Invalid expression atom '{atom}'", lineno)
    return idx + 1
