"""Renderer for the tmpl template engine."""

import collections.abc
import typing
from .lexer import TemplateRenderError, Token
from .parser import parse, TextNode, OutputNode, IfNode, ForNode

def render(source: str, context: dict | None = None, **kwargs) -> str:
    return Template(source).render(context, **kwargs)

class Template:
    def __init__(self, source: str):
        self.nodes = parse(source)

    def render(self, context: dict | None = None, **kwargs) -> str:
        ctx = {}
        if context:
            ctx.update(context)
        ctx.update(kwargs)
        return self._render_nodes(self.nodes, ctx, loop_info=None, token=None)

    def _render_nodes(self, nodes: list, ctx: dict, loop_info: dict | None, token: Token | None) -> str:
        parts = []
        for node in nodes:
            if isinstance(node, TextNode):
                parts.append(node.value)
            elif isinstance(node, OutputNode):
                parts.append(self._render_output(node.value, ctx, token))
            elif isinstance(node, IfNode):
                parts.append(self._render_if(node, ctx, loop_info))
            elif isinstance(node, ForNode):
                parts.append(self._render_for(node, ctx, loop_info))
        return "".join(parts)

    def _render_output(self, expr: str, ctx: dict, token: Token | None) -> str:
        value = self._evaluate_expression(expr, ctx, token)
        if value is None:
            return ""
        return str(value)

    def _render_if(self, node: IfNode, ctx: dict, loop_info: dict) -> str:
        for cond_str, body_nodes, _ in node.conditions:
            if self._evaluate_condition(cond_str, ctx, node.start_lineno):
                return self._render_nodes(body_nodes, ctx, loop_info, token=None)
        if node.else_nodes is not None:
            return self._render_nodes(node.else_nodes, ctx, loop_info, token=None)
        return ""

    def _render_for(self, node: ForNode, ctx: dict, loop_info: dict) -> str:
        value = self._evaluate_expression(node.expr, ctx, token=None)
        try:
            items = list(self._iterable_from(value))
        except TypeError:
            raise TemplateRenderError(f"Value is not iterable", node.start_lineno)

        new_ctx = ctx.copy()
        new_ctx['loop'] = None

        if not items:
            if node.else_nodes is not None:
                return self._render_nodes(node.else_nodes, ctx, loop_info, token=None)
            return ""

        loop_map = {
            'index': 1,
            'index0': 0,
            'first': True,
            'last': False,
            'length': len(items)
        }

        parts = []
        for i, item in enumerate(items):
            new_ctx[node.var_name] = item
            loop_map['index'] = i + 1
            loop_map['index0'] = i
            loop_map['first'] = (i == 0)
            loop_map['last'] = (i == len(items) - 1)
            new_ctx['loop'] = loop_map
            parts.append(self._render_nodes(node.body_nodes, new_ctx, loop_map, token=None))
        return "".join(parts)

    def _iterable_from(self, value) -> collections.abc.Iterable:
        if value is None:
            return []
        if isinstance(value, collections.abc.Mapping):
            return value.keys()
        if isinstance(value, (list, tuple)):
            return value
        try:
            return iter(value)
        except TypeError:
            raise TypeError(f"Value is not iterable")

    def _evaluate_expression(self, expr: str, ctx: dict, token: Token | None) -> typing.Any:
        # Handle literals
        if (expr.startswith('"') and expr.endswith('"')) or (expr.startswith("'") and expr.endswith("'")):
            return expr[1:-1]

        # Try integer
        try:
            return int(expr)
        except ValueError:
            pass

        # Handle filters
        if '|' in expr:
            parts = expr.split('|')
            base = parts[0].strip()
            value = self._resolve_path(base, ctx)
            for part in parts[1:]:
                part = part.strip()
                if ':' in part:
                    name, arg = part.split(':', 1)
                    name = name.strip()
                    arg = arg.strip()
                else:
                    name = part.strip()
                    arg = None
                value = self._apply_filter(name, value, arg, token)
            return value
        else:
            return self._resolve_path(expr, ctx)

    def _resolve_path(self, path: str, ctx: dict) -> typing.Any:
        parts = path.split('.')
        if not parts:
            return None
        current = ctx.get(parts[0], None)
        for part in parts[1:]:
            if current is None:
                return None
            if isinstance(current, collections.abc.Mapping):
                current = current.get(part, None)
            elif isinstance(current, (list, tuple)):
                try:
                    idx = int(part)
                    if 0 <= idx < len(current):
                        current = current[idx]
                    else:
                        return None
                except ValueError:
                    return None
            else:
                if not part.startswith('_'):
                    current = getattr(current, part, None)
                else:
                    current = None
        return current

    def _apply_filter(self, name: str, value: typing.Any, arg: str | None, token: Token | None) -> typing.Any:
        lineno = token.lineno if token else 0
        if name == 'upper':
            return str(value).upper()
        elif name == 'lower':
            return str(value).lower()
        elif name == 'trim':
            return str(value).strip()
        elif name == 'length':
            if value is None:
                return 0
            return len(value)
        elif name == 'first':
            if value is None or len(value) == 0:
                return None
            return value[0]
        elif name == 'last':
            if value is None or len(value) == 0:
                return None
            return value[-1]
        elif name == 'reverse':
            if value is None:
                return None
            if isinstance(value, str):
                return value[::-1]
            try:
                return list(value)[::-1]
            except TypeError:
                raise TemplateRenderError(f"Filter 'reverse' cannot be applied to this value", lineno)
        elif name == 'join':
            if value is None:
                return ""
            return arg.join(str(v) for v in value)
        elif name == 'default':
            if value is None or value == "":
                try:
                    return int(arg)
                except ValueError:
                    return arg
            return value
        elif name == 'truncate':
            N = int(arg)
            text = str(value)
            if len(text) > N:
                return text[:N] + "..."
            return text
        elif name == 'items':
            if value is None:
                return []
            if isinstance(value, collections.abc.Mapping):
                return list(value.items())
            raise TemplateRenderError(f"Filter 'items' cannot be applied to this value", lineno)
        else:
            raise TemplateRenderError(f"Unknown filter '{name}'", lineno)

    def _evaluate_condition(self, cond: str, ctx: dict, lineno: int) -> bool:
        tokens = self._tokenize_condition(cond)
        return self._evaluate_condition_tokens(tokens, 0, ctx)

    def _tokenize_condition(self, cond: str) -> list:
        words = cond.split()
        tokens = []
        for w in words:
            if w in ('and', 'or'):
                tokens.append(('logical', w))
            elif w == 'not':
                tokens.append(('logical', w))
            elif w in ('==', '!=', '<', '<=', '>', '>='):
                tokens.append(('op', w))
            else:
                tokens.append(('atom', w))
        return tokens

    def _evaluate_condition_tokens(self, tokens: list, idx: int, ctx: dict) -> bool:
        return self._evaluate_or(tokens, idx, ctx)

    def _evaluate_or(self, tokens: list, idx: int, ctx: dict) -> bool:
        left = self._evaluate_and(tokens, idx, ctx)
        idx = idx # Placeholder, logic below handles index

        # We need a parser that returns (value, new_idx)
        # Let's rewrite the evaluation to return (bool, int)
        pass

    def _evaluate_or_v2(self, tokens: list, idx: int, ctx: dict) -> tuple:
        val, idx = self._evaluate_and_v2(tokens, idx, ctx)
        while idx < len(tokens) and tokens[idx][0] == 'logical' and tokens[idx][1] == 'or':
            idx += 1
            if val:
                return True, idx # Short circuit
            val, idx = self._evaluate_and_v2(tokens, idx, ctx)
        return val, idx

    def _evaluate_and_v2(self, tokens: list, idx: int, ctx: dict) -> tuple:
        val, idx = self._evaluate_not_v2(tokens, idx, ctx)
        while idx < len(tokens) and tokens[idx][0] == 'logical' and tokens[idx][1] == 'and':
            idx += 1
            if not val:
                return False, idx # Short circuit
            val, idx = self._evaluate_not_v2(tokens, idx, ctx)
        return val, idx

    def _evaluate_not_v2(self, tokens: list, idx: int, ctx: dict) -> tuple:
        if idx < len(tokens) and tokens[idx][0] == 'logical' and tokens[idx][1] == 'not':
            idx += 1
            val, idx = self._evaluate_not_v2(tokens, idx, ctx)
            return not val, idx
        return self._evaluate_comparison_v2(tokens, idx, ctx)

    def _evaluate_comparison_v2(self, tokens: list, idx: int, ctx: dict) -> tuple:
        val, idx = self._evaluate_atom_v2(tokens, idx, ctx)
        if idx < len(tokens) and tokens[idx][0] == 'op':
            op = tokens[idx][1]
            idx += 1
            right, idx = self._evaluate_atom_v2(tokens, idx, ctx)
            try:
                if op == '==': return (val == right), idx
                if op == '!=': return (val != right), idx
                if op == '<': return (val < right), idx
                if op == '<=': return (val <= right), idx
                if op == '>': return (val > right), idx
                if op == '>=': return (val >= right), idx
            except TypeError:
                raise TemplateRenderError(f"Cannot compare values", 0) # Lineno from caller
        return bool(val), idx

    def _evaluate_atom_v2(self, tokens: list, idx: int, ctx: dict) -> tuple:
        if idx >= len(tokens) or tokens[idx][0] != 'atom':
            return None, idx
        atom = tokens[idx][1]
        val = self._evaluate_expression(atom, ctx, token=None)
        return val, idx + 1

    def _evaluate_condition(self, cond: str, ctx: dict, lineno: int) -> bool:
        tokens = self._tokenize_condition(cond)
        val, _ = self._evaluate_or_v2(tokens, 0, ctx)
        return val
