# sheet/formula.py
import re
from typing import Set, Any, Callable, Union

class ErrorValue(str):
    pass

ERROR = ErrorValue('#ERROR!')
CYCLE = ErrorValue('#CYCLE!')

class FormulaError(ValueError):
    pass

def _is_valid_ref(s: str) -> bool:
    if len(s) < 2:
        return False
    col_part = s[:-1]
    row_part = s[-1:]
    # Column: must be one uppercase letter A-Z
    if len(col_part) != 1 or not ('A' <= col_part <= 'Z'):
        return False
    # Row: digits, no leading zero unless it is just "0" but 0 is not allowed (1-999)
    if not row_part.isdigit():
        return False
    val = int(row_part)
    if val < 1 or val > 999:
        return False
    # Check for leading zero: if length > 1 and starts with 0
    if len(row_part) > 1 and row_part[0] == '0':
        return False
    return True

def _parse_ref(name: str) -> str:
    # name is already validated and uppercased
    return name.upper()

# Token types
TOK_NUMBER = 'NUMBER'
TOK_REF = 'REF'
TOK_PLUS = 'PLUS'
TOK_MINUS = 'MINUS'
TOK_MUL = 'MUL'
TOK_DIV = 'DIV'
TOK_LPAREN = 'LPAREN'
TOK_RPAREN = 'RPAREN'
TOK_EOF = 'EOF'

def tokenize(source: str) -> list:
    tokens = []
    i = 0
    n = len(source)
    while i < n:
        if source[i].isspace():
            i += 1
            continue
        if source[i].isdigit():
            j = i
            while j < n and source[j].isdigit():
                j += 1
            if j < n and source[j] == '.':
                j += 1
                while j < n and source[j].isdigit():
                    j += 1
                num_str = source[i:j]
                if '.' in num_str:
                    val = float(num_str)
                else:
                    val = int(num_str)
                tokens.append((TOK_NUMBER, val))
                i = j
            else:
                tokens.append((TOK_NUMBER, int(source[i:j])))
                i = j
        elif source[i].isalpha():
            j = i
            while j < n and source[j].isalpha():
                j += 1
            ref_str = source[i:j]
            # Validate reference
            # Reference must be letters followed by digits
            # But our grammar says ref := letters digits
            # So we need at least one letter then at least one digit
            # Find where digits start
            k = i
            while k < j and not source[k].isdigit():
                k += 1
            if k == j:
                # No digit found, it's not a valid ref
                raise FormulaError(f"Invalid token: {ref_str}")
            ref_name = ref_str[:k] + ref_str[k:] # full string
            if not _is_valid_ref(ref_name.upper()):
                raise FormulaError(f"Invalid reference: {ref_name}")
            tokens.append((TOK_REF, ref_name.upper()))
            i = j
        elif source[i] == '+':
            tokens.append((TOK_PLUS, '+'))
            i += 1
        elif source[i] == '-':
            tokens.append((TOK_MINUS, '-'))
            i += 1
        elif source[i] == '*':
            tokens.append((TOK_MUL, '*'))
            i += 1
        elif source[i] == '/':
            tokens.append((TOK_DIV, '/'))
            i += 1
        elif source[i] == '(':
            tokens.append((TOK_LPAREN, '('))
            i += 1
        elif source[i] == ')':
            tokens.append((TOK_RPAREN, ')'))
            i += 1
        else:
            raise FormulaError(f"Unknown character: {source[i]}")
    tokens.append((TOK_EOF, None))
    return tokens

# AST Nodes
class NumNode:
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode:
    def __init__(self, name: str):
        self.name = name

class UnaryNode:
    def __init__(self, op: str, operand):
        self.op = op  # '+' or '-'
        self.operand = operand

class BinaryNode:
    def __init__(self, op: str, left, right):
        self.op = op
        self.left = left
        self.right = right

class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def eat(self, token_type):
        tok, val = self.current()
        if tok != token_type:
            raise FormulaError(f"Expected {token_type}, got {tok}")
        self.pos += 1
        return val

    def parse(self):
        node = self.parse_expr()
        if self.current()[0] != TOK_EOF:
            raise FormulaError("Unexpected token after expression")
        return node

    def parse_expr(self):
        node = self.parse_term()
        while True:
            tok, val = self.current()
            if tok in (TOK_PLUS, TOK_MINUS):
                self.pos += 1
                right = self.parse_term()
                node = BinaryNode(val, node, right)
            else:
                break
        return node

    def parse_term(self):
        node = self.parse_unary()
        while True:
            tok, val = self.current()
            if tok in (TOK_MUL, TOK_DIV):
                self.pos += 1
                right = self.parse_unary()
                node = BinaryNode(val, node, right)
            else:
                break
        return node

    def parse_unary(self):
        tok, val = self.current()
        if tok == TOK_PLUS:
            self.pos += 1
            operand = self.parse_unary()
            return UnaryNode('+', operand)
        elif tok == TOK_MINUS:
            self.pos += 1
            operand = self.parse_unary()
            return UnaryNode('-', operand)
        else:
            return self.parse_primary()

    def parse_primary(self):
        tok, val = self.current()
        if tok == TOK_NUMBER:
            self.pos += 1
            return NumNode(val)
        elif tok == TOK_REF:
            self.pos += 1
            return RefNode(val)
        elif tok == TOK_LPAREN:
            self.pos += 1
            node = self.parse_expr()
            self.eat(TOK_RPAREN)
            return node
        else:
            raise FormulaError(f"Unexpected token: {tok}")

def parse_formula(source: str) -> Any:
    if not source or source.strip() == '':
        raise FormulaError("Empty formula")
    tokens = tokenize(source)
    if len(tokens) == 0 or (len(tokens) == 1 and tokens[0][0] == TOK_EOF):
        raise FormulaError("Empty formula")
    parser = Parser(tokens)
    return parser.parse()

def references(tree: Any) -> Set[str]:
    refs = set()
    if isinstance(tree, RefNode):
        refs.add(tree.name)
    elif isinstance(tree, UnaryNode):
        refs |= references(tree.operand)
    elif isinstance(tree, BinaryNode):
        refs |= references(tree.left)
        refs |= references(tree.right)
    return refs

def _is_error(val: Any) -> bool:
    return isinstance(val, ErrorValue)

def evaluate(tree: Any, lookup: Callable[[str], Any]) -> Any:
    if isinstance(tree, NumNode):
        return tree.value
    elif isinstance(tree, RefNode):
        val = lookup(tree.name)
        if val is None:
            return 0
        return val
    elif isinstance(tree, UnaryNode):
        operand_val = evaluate(tree.operand, lookup)
        if _is_error(operand_val):
            return operand_val
        if isinstance(operand_val, str):
            return ERROR
        if tree.op == '+':
            return operand_val
        else:
            return -operand_val
    elif isinstance(tree, BinaryNode):
        left_val = evaluate(tree.left, lookup)
        if _is_error(left_val):
            # If right is also error, return left
            right_val = evaluate(tree.right, lookup)
            if _is_error(right_val):
                return left_val
            return left_val
        if _is_error(left_val):
            return left_val

        right_val = evaluate(tree.right, lookup)
        if _is_error(right_val):
            return left_val # left is not error, right is error -> left? 
            # Rule: "If an operand is an error value, the result is that error value (the left one if both are)."
            # This implies if left is error, return left. If left is not error but right is, return right?
            # Let's re-read: "If an operand is an error value, the result is that error value"
            # So if either is error, return the error value. If both, return left.
            # My code above: if left is error, return left (correct). If left not error but right is, I return left which is WRONG.

        # Let's correct:
        # Check errors again properly
        if _is_error(left_val):
            if _is_error(right_val):
                return left_val
            return left_val
        if _is_error(right_val):
            return right_val

        # Both are not errors
        if isinstance(left_val, str) or isinstance(right_val, str):
            return ERROR

        if tree.op == '+':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val + right_val
            else:
                return float(left_val) + float(right_val)
        elif tree.op == '-':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val - right_val
            else:
                return float(left_val) - float(right_val)
        elif tree.op == '*':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val * right_val
            else:
                return float(left_val) * float(right_val)
        elif tree.op == '/':
            if right_val == 0:
                return ERROR
            return float(left_val) / float(right_val)
    return ERROR
