import re
from .formula import parse_formula, evaluate, references, FormulaError, ErrorValue, ERROR, CYCLE
from .graph import DependencyGraph

class Sheet:
    def __init__(self):
        self._graph = DependencyGraph()
        # _data: name -> raw string
        self._data: dict[str, str] = {}
        # _values: name -> value
        self._values: dict[str, any] = {}
        # _eval_count
        self.evaluations: int = 0

    def _validate_name(self, name: str):
        if len(name) != 2:
            raise ValueError(f"Invalid cell name: {name}")
        col = name[0]
        row_str = name[1]
        if not ('A' <= col <= 'Z'):
            raise ValueError(f"Invalid column: {col}")
        if not row_str.isdigit():
            raise ValueError(f"Invalid row: {row_str}")
        row = int(row_str)
        if row < 1 or row > 999:
            raise ValueError(f"Invalid row: {row}")
        if len(row_str) > 1 and row_str[0] == '0':
            raise ValueError(f"Leading zero in row: {row_str}")

    def _normalize_name(self, name: str) -> str:
        return name.upper()

    def _is_formula(self, raw: str) -> bool:
        return raw.strip().startswith('=')

    def _is_number(self, raw: str) -> bool:
        s = raw.strip()
        if s.startswith('-'):
            s = s[1:]
        if not s:
            return False
        if '.' in s:
            parts = s.split('.')
            if len(parts) != 2:
                return False
            if not parts[0].isdigit() or not parts[1].isdigit():
                return False
            if len(parts[0]) == 0 and len(parts[1]) == 0:
                return False
        else:
            if not s.isdigit():
                return False
        return True

    def _parse_number(self, raw: str) -> any:
        s = raw.strip()
        if s.startswith('-'):
            s = s[1:]
        if '.' in s:
            return float(s)
        else:
            return int(s)

    def _get_value(self, name: str) -> any:
        if name not in self._values:
            return None
        return self._values[name]

    def _is_cycle(self, name: str) -> bool:
        return name in self._graph.cycle_cells()

    def _recalculate(self, changed: set[str]) -> list[str]:
        # Get all dependents in row-major order
        all_cells = set()
        for c in changed:
            all_cells.add(c)
            all_cells |= self._graph.all_dependents(c)

        # Remove cells that are on cycles or refer to cycles? 
        # Rule: "A cell on a cycle has the value #CYCLE! and is not evaluated."
        # "A cell that refers to a #CYCLE! cell gets #CYCLE! through rule 3 of evaluation."
        # We need to determine which cells to evaluate.

        # First, mark cycle cells
        cycle_cells = self._graph.cycle_cells()

        # Determine evaluation order: topological sort of dependents
        # Only evaluate cells that are not on cycles and whose precedents are all evaluated

        # Let's collect all non-cycle cells that need evaluation
        to_eval = set()
        for c in all_cells:
            if c in cycle_cells:
                continue
            # Check if any precedent is on a cycle
            has_cycle_prec = False
            for prec in self._graph.precedents(c):
                if prec in cycle_cells:
                    has_cycle_prec = True
                    break
            if not has_cycle_prec:
                to_eval.add(c)
            else:
                # This cell will become #CYCLE!
                self._values[c] = CYCLE
                if c in self._data:
                    pass # keep raw

        # Topological sort of to_eval based on precedents within to_eval
        # Compute in-degree for each cell in to_eval (only counting precedents in to_eval)
        in_degree = {}
        prec_map = {}
        for c in to_eval:
            precs = [p for p in self._graph.precedents(c) if p in to_eval]
            prec_map[c] = precs
            in_degree[c] = len(precs)

        queue = [c for c in to_eval if in_degree[c] == 0]
        order = []
        while queue:
            # Sort queue by row-major order to ensure deterministic order
            queue.sort(key=self._row_major_key)
            c = queue.pop(0)
            order.append(c)
            for dependent in self._graph.dependents(c):
                if dependent in to_eval:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        queue.append(dependent)

        # Evaluate in order
        for c in order:
            raw = self._data[c]
            if self._is_formula(raw):
                try:
                    tree = parse_formula(raw[1:])
                    refs = references(tree)
                    # Update graph
                    self._graph.set_dependencies(c, refs)

                    # Lookup values
                    def lookup(name: str) -> any:
                        val = self._values.get(name, None)
                        if val is None:
                            return 0
                        return val

                    result = evaluate(tree, lookup)
                    self._values[c] = result
                    self.evaluations += 1
                except FormulaError:
                    # If formula is invalid after set, it should have been caught in set()
                    pass
            else:
                # It's text or number
                if raw == '':
                    self._values[c] = None
                elif self._is_number(raw):
                    self._values[c] = self._parse_number(raw)
                else:
                    self._values[c] = raw

        # Handle cells that depend on cycle cells
        # We already marked them as #CYCLE! above. But let's make sure all dependents of cycle cells are also #CYCLE!
        # Actually, the rule says "A cell that refers to a #CYCLE! cell gets #CYCLE! through rule 3 of evaluation."
        # This means we should evaluate them? No, it means the result of evaluation is #CYCLE!.
        # But we skipped them. Let's mark them.

        # Actually, let's redo: any cell whose precedent is #CYCLE! or is on a cycle should be #CYCLE!
        # But we need to propagate. Let's find all cells that eventually depend on a cycle cell.

        # Get all cycle cells
        # Any cell that has a precedent in cycle_cells or has a precedent that is #CYCLE! (which might be propagated)
        # Let's use BFS from cycle cells through dependents

        # First, mark all cycle cells
        for c in cycle_cells:
            if c in self._data:
                self._values[c] = CYCLE

        # Then propagate
        # All cells that are in all_dependents of cycle_cells should be checked
        # But we already handled to_eval. Let's mark all dependents of cycle cells as #CYCLE!
        for c in cycle_cells:
            for dep in self._graph.all_dependents(c):
                if dep != c: # c is already marked
                    # But wait, dep might be evaluated if it doesn't directly depend on a cycle?
                    # No, if it depends on a cycle cell, it will get #CYCLE!
                    if dep in all_cells and dep not in to_eval:
                        self._values[dep] = CYCLE
                    elif dep not in to_eval:
                        self._values[dep] = CYCLE

        # Return all affected cells in row-major order
        all_affected = set()
        for c in changed:
            all_affected.add(c)
            all_affected |= self._graph.all_dependents(c)

        return sorted(list(all_affected), key=self._row_major_key)

    def _row_major_key(self, name: str) -> tuple:
        col = ord(name[0]) - ord('A')
        row = int(name[1:])
        return (row, col)

    def set(self, name: str, raw: str) -> list[str]:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")

        name = self._normalize_name(name)
        self._validate_name(name)

        # Validate formula if applicable
        if raw.strip().startswith('='):
            try:
                parse_formula(raw[1:])
            except FormulaError:
                raise

        # Store raw
        self._data[name] = raw

        # Remove old precedents for this cell
        if name in self._graph.precedents():
            self._graph.set_dependencies(name, set())

        # If it's a formula, update precedents
        if raw.strip().startswith('='):
            tree = parse_formula(raw[1:])
            refs = references(tree)
            self._graph.set_dependencies(name, refs)

        # Recalculate
        return self._recalculate([name])

    def get(self, name: str) -> any:
        name = self._normalize_name(name)
        self._validate_name(name)
        return self._values.get(name, None)

    def raw(self, name: str) -> str:
        name = self._normalize_name(name)
        self._validate_name(name)
        return self._data.get(name, '')

    def cells(self) -> list[str]:
        non_empty = []
        for name in sorted(self._data.keys(), key=self._row_major_key):
            if self._data[name] != '':
                non_empty.append(name)
        return non_empty
