# sheet/graph.py
from typing import Set, Dict

class DependencyGraph:
    def __init__(self):
        # precedents: cell -> set of cells it refers to
        self._precedents: Dict[str, Set[str]] = {}
        # dependents: cell -> set of cells that refer to it
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: set):
        # Remove old entries
        old_precs = self._precedents.get(cell, set())
        for p in old_precs:
            if p in self._dependents:
                self._dependents[p].discard(cell)

        # Set new entries
        self._precedents[cell] = set(precedents)
        for p in precedents:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell: str) -> Set[str]:
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell: str) -> Set[str]:
        # BFS/DFS from cell through dependents
        visited = set()
        stack = [cell]
        while stack:
            c = stack.pop()
            if c in visited:
                continue
            visited.add(c)
            for d in self._dependents.get(c, set()):
                if d not in visited:
                    stack.append(d)
        return visited

    def cycle_cells(self) -> Set[str]:
        # Find all cells that are part of a cycle
        cells = set(self._precedents.keys()) | set(self._dependents.keys())
        result = set()
        for start in cells:
            # DFS from start, looking for a path back to start
            visited = set()
            stack = [(start, [start])]
            found_cycle = False
            while stack and not found_cycle:
                node, path = stack.pop()
                for neighbor in self._precedents.get(node, set()):
                    if neighbor == start and len(path) > 1:
                        found_cycle = True
                        break
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append((neighbor, path + [neighbor]))
            if found_cycle:
                result.add(start)
        return result
