# sheet/formula.py
import re
from typing import Set, Any, Callable, Union

class ErrorValue(str):
    """
    Error value subclass of str. Compares equal to its text representation.
    """
    pass

ERROR = ErrorValue('#ERROR!')
CYCLE = ErrorValue('#CYCLE!')

class FormulaError(ValueError):
    """Raised when formula parsing fails."""
    pass

# Token types
TOK_NUMBER = 'NUMBER'
TOK_REF = 'REF'
TOK_PLUS = 'PLUS'
TOK_MINUS = 'MINUS'
TOK_MUL = 'MUL'
TOK_DIV = 'DIV'
TOK_LPAREN = 'LPAREN'
TOK_RPAREN = 'RPAREN'
TOK_EOF = 'EOF'

class NumNode:
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode:
    def __init__(self, name: str):
        self.name = name

class UnaryNode:
    def __init__(self, op: str, operand):
        self.op = op  # '+' or '-'
        self.operand = operand

class BinaryNode:
    def __init__(self, op: str, left, right):
        self.op = op
        self.left = left
        self.right = right

def _is_valid_ref(s: str) -> bool:
    """
    Validates a cell reference string (e.g., 'A1', 'Z999').
    - Column: Single letter A-Z.
    - Row: Digits 1-999, no leading zeros.
    """
    if len(s) < 2:
        return False
    col_part = s[:-1]
    row_part = s[-1:]

    # Column: must be exactly one uppercase letter A-Z
    if len(col_part) != 1 or not ('A' <= col_part <= 'Z'):
        return False

    # Row: must be digits
    if not row_part.isdigit():
        return False

    # Row value check: 1-999
    val = int(row_part)
    if val < 1 or val > 999:
        return False

    # Leading zero check: if length > 1 and starts with '0'
    if len(row_part) > 1 and row_part[0] == '0':
        return False

    return True

def tokenize(source: str) -> list:
    """
    Tokenizes the formula string.
    Raises FormulaError for invalid characters or references.
    """
    tokens = []
    i = 0
    n = len(source)
    while i < n:
        if source[i].isspace():
            i += 1
            continue

        if source[i].isdigit():
            j = i
            while j < n and source[j].isdigit():
                j += 1
            # Check for decimal point
            if j < n and source[j] == '.':
                j += 1
                while j < n and source[j].isdigit():
                    j += 1
                num_str = source[i:j]
                if '.' in num_str:
                    val = float(num_str)
                else:
                    val = int(num_str)
                tokens.append((TOK_NUMBER, val))
                i = j
            else:
                tokens.append((TOK_NUMBER, int(source[i:j])))
                i = j

        elif source[i].isalpha():
            # Read letters
            k = i
            while k < n and source[k].isalpha():
                k += 1

            # Read digits following letters
            m = k
            while m < n and source[m].isdigit():
                m += 1

            ref_str = source[i:m]

            # Validate reference
            if not _is_valid_ref(ref_str):
                raise FormulaError(f"Invalid reference: {ref_str}")

            tokens.append((TOK_REF, ref_str.upper()))
            i = m

        elif source[i] == '+':
            tokens.append((TOK_PLUS, '+'))
            i += 1
        elif source[i] == '-':
            tokens.append((TOK_MINUS, '-'))
            i += 1
        elif source[i] == '*':
            tokens.append((TOK_MUL, '*'))
            i += 1
        elif source[i] == '/':
            tokens.append((TOK_DIV, '/'))
            i += 1
        elif source[i] == '(':
            tokens.append((TOK_LPAREN, '('))
            i += 1
        elif source[i] == ')':
            tokens.append((TOK_RPAREN, ')'))
            i += 1
        else:
            raise FormulaError(f"Unknown character: {source[i]}")

    tokens.append((TOK_EOF, None))
    return tokens

class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def eat(self, token_type):
        tok, val = self.current()
        if tok != token_type:
            raise FormulaError(f"Expected {token_type}, got {tok}")
        self.pos += 1
        return val

    def parse(self):
        node = self.parse_expr()
        if self.current()[0] != TOK_EOF:
            raise FormulaError("Unexpected token after expression")
        return node

    def parse_expr(self):
        node = self.parse_term()
        while True:
            tok, val = self.current()
            if tok in (TOK_PLUS, TOK_MINUS):
                self.pos += 1
                right = self.parse_term()
                node = BinaryNode(val, node, right)
            else:
                break
        return node

    def parse_term(self):
        node = self.parse_unary()
        while True:
            tok, val = self.current()
            if tok in (TOK_MUL, TOK_DIV):
                self.pos += 1
                right = self.parse_unary()
                node = BinaryNode(val, node, right)
            else:
                break
        return node

    def parse_unary(self):
        tok, val = self.current()
        if tok == TOK_PLUS:
            self.pos += 1
            operand = self.parse_unary()
            return UnaryNode('+', operand)
        elif tok == TOK_MINUS:
            self.pos += 1
            operand = self.parse_unary()
            return UnaryNode('-', operand)
        else:
            return self.parse_primary()

    def parse_primary(self):
        tok, val = self.current()
        if tok == TOK_NUMBER:
            self.pos += 1
            return NumNode(val)
        elif tok == TOK_REF:
            self.pos += 1
            return RefNode(val)
        elif tok == TOK_LPAREN:
            self.pos += 1
            node = self.parse_expr()
            self.eat(TOK_RPAREN)
            return node
        else:
            raise FormulaError(f"Unexpected token: {tok}")

def parse_formula(source: str) -> Any:
    """
    Parses the text after '=' and returns a syntax tree.
    Raises FormulaError for empty input, invalid characters, incomplete expression,
    unbalanced parentheses, or invalid references.
    """
    if not source or source.strip() == '':
        raise FormulaError("Empty formula")
    tokens = tokenize(source)
    if len(tokens) == 0 or (len(tokens) == 1 and tokens[0][0] == TOK_EOF):
        raise FormulaError("Empty formula")
    parser = Parser(tokens)
    return parser.parse()

def references(tree: Any) -> Set[str]:
    """Returns the upper-case names of the cells the formula refers to."""
    refs = set()
    if isinstance(tree, RefNode):
        refs.add(tree.name)
    elif isinstance(tree, UnaryNode):
        refs |= references(tree.operand)
    elif isinstance(tree, BinaryNode):
        refs |= references(tree.left)
        refs |= references(tree.right)
    return refs

def _is_error(val: Any) -> bool:
    return isinstance(val, ErrorValue)

def evaluate(tree: Any, lookup: Callable[[str], Any]) -> Any:
    """
    Computes the formula's value.
    lookup(name) takes an upper-case name and returns that cell's current value.
    """
    if isinstance(tree, NumNode):
        return tree.value
    elif isinstance(tree, RefNode):
        val = lookup(tree.name)
        if val is None:
            return 0
        return val
    elif isinstance(tree, UnaryNode):
        operand_val = evaluate(tree.operand, lookup)
        if _is_error(operand_val):
            return operand_val
        if isinstance(operand_val, str):
            return ERROR
        if tree.op == '+':
            return operand_val
        else:
            return -operand_val
    elif isinstance(tree, BinaryNode):
        left_val = evaluate(tree.left, lookup)
        if _is_error(left_val):
            return left_val

        right_val = evaluate(tree.right, lookup)
        if _is_error(right_val):
            return right_val

        # Both are not errors
        if isinstance(left_val, str) or isinstance(right_val, str):
            return ERROR

        if tree.op == '+':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val + right_val
            else:
                return float(left_val) + float(right_val)
        elif tree.op == '-':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val - right_val
            else:
                return float(left_val) - float(right_val)
        elif tree.op == '*':
            if isinstance(left_val, int) and isinstance(right_val, int):
                return left_val * right_val
            else:
                return float(left_val) * float(right_val)
        elif tree.op == '/':
            if right_val == 0:
                return ERROR
            return float(left_val) / float(right_val)
    return ERROR
