from .formula import parse_formula, evaluate, references, FormulaError, ErrorValue, ERROR, CYCLE
from .graph import DependencyGraph
from typing import Any, Callable

class Sheet:
    def __init__(self):
        self._graph = DependencyGraph()
        # _data: name -> raw string
        self._data: dict[str, str] = {}
        # _values: name -> value
        self._values: dict[str, Any] = {}
        # _eval_count
        self.evaluations: int = 0

    def _validate_name(self, name: str):
        if len(name) < 2 or len(name) > 4: # A1 to Z999 is max 4 chars
            raise ValueError(f"Invalid cell name: {name}")
        col = name[0]
        row_str = name[1:]
        if not ('A' <= col <= 'Z'):
            raise ValueError(f"Invalid column: {col}")
        if not row_str.isdigit():
            raise ValueError(f"Invalid row: {row_str}")
        row = int(row_str)
        if row < 1 or row > 999:
            raise ValueError(f"Invalid row: {row}")
        if len(row_str) > 1 and row_str[0] == '0':
            raise ValueError(f"Leading zero in row: {row_str}")

    def _normalize_name(self, name: str) -> str:
        return name.upper()

    def _is_formula(self, raw: str) -> bool:
        return raw.strip().startswith('=')

    def _is_number(self, raw: str) -> bool:
        s = raw.strip()
        if not s:
            return False
        if s.startswith('-'):
            s = s[1:]
            if not s:
                return False
        if '.' in s:
            parts = s.split('.')
            if len(parts) != 2:
                return False
            if not parts[0].isdigit() or not parts[1].isdigit():
                return False
            # Allow empty left or right side of decimal? 
            # Grammar says "digits [. digits]", implying at least one digit.
            # But typically 1. is 1.0. Let's stick to strict digits requirement if possible.
            # The spec says "digits [. digits]". It doesn't explicitly forbid 1. or .1.
            # However, "number := digits [. digits]" usually implies non-empty groups in formal grammar contexts unless specified.
            # Let's assume standard float parsing which allows 1. but let's be safe with isdigit checks.
            if not (parts[0] or parts[1]):
                 return False
        else:
            if not s.isdigit():
                return False
        return True

    def _parse_number(self, raw: str) -> Any:
        s = raw.strip()
        if s.startswith('-'):
            s = s[1:]
        if '.' in s:
            return float(s)
        else:
            return int(s)

    def _get_value(self, name: str) -> Any:
        if name not in self._values:
            return None
        return self._values[name]

    def _row_major_key(self, name: str) -> tuple:
        col = ord(name[0]) - ord('A')
        row = int(name[1:])
        return (row, col)

    def _recalculate(self, changed: list[str]) -> list[str]:
        # Get all dependents in row-major order
        all_cells = set()
        for c in changed:
            all_cells.add(c)
            all_cells |= self._graph.all_dependents(c)

        # Determine cycle cells
        cycle_cells = self._graph.cycle_cells()

        # Mark cycle cells with #CYCLE!
        for c in cycle_cells:
            if c in self._data:
                self._values[c] = CYCLE

        # Propagate #CYCLE! to all dependents of cycle cells
        # Any cell that is a dependent of a cycle cell (directly or indirectly)
        # should evaluate to #CYCLE! if it's in the affected set
        for c in cycle_cells:
            for dep in self._graph.all_dependents(c):
                if dep != c: # c is already marked
                    if dep in all_cells:
                        self._values[dep] = CYCLE

        # Determine which cells to actually evaluate
        to_eval = []
        for c in all_cells:
            # Skip if it's a cycle cell (already marked)
            if c in cycle_cells:
                continue
            # Skip if it was marked #CYCLE! by propagation
            if self._values.get(c) == CYCLE:
                continue
            to_eval.append(c)

        # Topological sort (Kahn's algorithm)
        in_degree = {c: 0 for c in to_eval}

        for c in to_eval:
            prec_count = 0
            for prec in self._graph.precedents(c):
                if prec in to_eval:
                    prec_count += 1
            in_degree[c] = prec_count

        queue = [c for c in to_eval if in_degree[c] == 0]
        queue.sort(key=self._row_major_key)

        evaluated_order = []

        while queue:
            c = queue.pop(0)
            evaluated_order.append(c)

            for dep in self._graph.dependents(c):
                if dep in in_degree:
                    in_degree[dep] -= 1
                    if in_degree[dep] == 0:
                        queue.append(dep)
            queue.sort(key=self._row_major_key)

        # Evaluate in topological order
        for c in evaluated_order:
            raw = self._data[c]
            if self._is_formula(raw):
                tree = parse_formula(raw[1:])

                def lookup(name: str) -> Any:
                    val = self._values.get(name, None)
                    if val is None:
                        return 0
                    return val

                result = evaluate(tree, lookup)
                self._values[c] = result
                self.evaluations += 1
            else:
                # It's text or number
                if raw == '':
                    self._values[c] = None
                elif self._is_number(raw):
                    self._values[c] = self._parse_number(raw)
                else:
                    self._values[c] = raw

        # Ensure all cells in all_cells have a value
        for c in all_cells:
            if c not in self._values:
                if c in cycle_cells:
                    self._values[c] = CYCLE
                elif any(self._values.get(prec) == CYCLE for prec in self._graph.precedents(c)):
                    self._values[c] = CYCLE
                else:
                    # Fallback: evaluate if not formula? 
                    # If it's in all_cells, it should have been processed.
                    # If it's not a formula and not in to_eval, it might be because it wasn't in changed/dependents?
                    # But all_cells is changed + all_dependents(changed).
                    # If it's not in to_eval, it means it was skipped (cycle or propagated CYCLE).
                    # If it's not in _values, it means it was never set.
                    # This case should ideally not happen for non-formula cells that are "empty" or "text".
                    # If raw is empty, value is None. If raw is text, value is text.
                    # We need to ensure _values is populated for all cells in _data that are in all_cells.
                    if c in self._data:
                        raw = self._data[c]
                        if raw == '':
                            self._values[c] = None
                        elif self._is_number(raw):
                            self._values[c] = self._parse_number(raw)
                        else:
                            self._values[c] = raw

        # Return all affected cells in row-major order
        all_affected = set()
        for c in changed:
            all_affected.add(c)
            all_affected |= self._graph.all_dependents(c)

        return sorted(list(all_affected), key=self._row_major_key)

    def set(self, name: str, raw: str) -> list[str]:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")

        name = self._normalize_name(name)
        self._validate_name(name)

        # Validate formula if applicable BEFORE changing state
        if raw.strip().startswith('='):
            try:
                parse_formula(raw[1:])
            except FormulaError:
                raise

        # Store raw
        self._data[name] = raw

        # Remove old precedents for this cell
        self._graph.set_dependencies(name, set())

        # If it's a formula, update precedents
        if raw.strip().startswith('='):
            tree = parse_formula(raw[1:])
            refs = references(tree)
            self._graph.set_dependencies(name, refs)

        # Recalculate
        return self._recalculate([name])

    def get(self, name: str) -> Any:
        name = self._normalize_name(name)
        self._validate_name(name)
        return self._values.get(name, None)

    def raw(self, name: str) -> str:
        name = self._normalize_name(name)
        self._validate_name(name)
        return self._data.get(name, '')

    def cells(self) -> list[str]:
        non_empty = []
        # We need to iterate over all possible cells? No, only those in _data.
        # But _data only contains cells that have been set.
        # The requirement says "returns the non-empty cells".
        # A cell is non-empty if its raw string is not ''.
        for name in self._data:
            if self._data[name] != '':
                non_empty.append(name)
        return sorted(non_empty, key=self._row_major_key)
