# sheet/graph.py
from typing import Set, Dict, List

class DependencyGraph:
    def __init__(self):
        # precedents: cell -> set of cells it refers to
        self._precedents: Dict[str, Set[str]] = {}
        # dependents: cell -> set of cells that refer to it
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Set[str]):
        # Remove old entries
        old_precs = self._precedents.get(cell, set())
        for p in old_precs:
            if p in self._dependents:
                self._dependents[p].discard(cell)

        # Set new entries
        self._precedents[cell] = set(precedents)
        for p in precedents:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell: str) -> Set[str]:
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell: str) -> Set[str]:
        # BFS/DFS from cell through dependents
        visited = set()
        queue = [cell]
        while queue:
            c = queue.pop()
            if c in visited:
                continue
            visited.add(c)
            for d in self._dependents.get(c, set()):
                if d not in visited:
                    queue.append(d)
        return visited

    def cycle_cells(self) -> Set[str]:
        """
        Returns every cell that lies on a cycle.
        A cell is on a cycle if there is a path from it back to itself.
        """
        all_nodes = set(self._precedents.keys()) | set(self._dependents.keys())
        in_cycle = set()

        # Use Tarjan's algorithm or simple DFS coloring to find SCCs
        # Given the small size, we can also do a simpler check:
        # A node is in a cycle if it is part of a Strongly Connected Component (SCC)
        # with more than 1 node, or has a self-loop.

        # Implementing simple DFS-based SCC detection (Tarjan's)
        index_counter = [0]
        stack = []
        lowlink = {}
        index = {}
        on_stack = {}

        def strongconnect(v):
            index[v] = index_counter[0]
            lowlink[v] = index_counter[0]
            index_counter[0] += 1
            on_stack[v] = True
            stack.append(v)

            for w in self._precedents.get(v, set()):
                if w not in index:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif on_stack.get(w, False):
                    lowlink[v] = min(lowlink[v], index[w])

            # If v is a root node, pop the stack and generate an SCC
            if lowlink[v] == index[v]:
                scc = set()
                while True:
                    w = stack.pop()
                    on_stack[w] = False
                    scc.add(w)
                    if w == v:
                        break
                # If SCC has size > 1 or node has self-loop, it's a cycle
                if len(scc) > 1 or v in self._precedents.get(v, set()):
                    in_cycle.update(scc)

        for v in all_nodes:
            if v not in index:
                strongconnect(v)

        return in_cycle
